from typing import Optional
from dataclasses import dataclass
from collections import defaultdict, deque

class Helpdesk:
    """A ticket queue for a customer helpdesk."""
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        """Initialize the helpdesk."""
        self.tickets = {}
        self.queue = defaultdict(deque)
        self.vip_queue = defaultdict(deque)
        self.customer_vip_status = {}
        self.ticket_id_counter = 0
        self.closed_tickets = set()

    def add_customer(self, name: str, vip: bool = False) -> None:
        """Add a customer to the helpdesk."""
        self.customer_vip_status[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Title cannot be empty")
        if priority not in self.PRIORITIES:
            raise ValueError("Invalid priority")

        self.ticket_id_counter += 1
        ticket_id = self.ticket_id_counter
        self.tickets[ticket_id] = (customer, title, priority)

        if self.customer_vip_status[customer]:
            self.vip_queue[priority].append(ticket_id)
        else:
            self.queue[priority].append(ticket_id)

        return ticket_id

    def next_ticket(self) -> Optional[int]:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        for priority in self.PRIORITIES[::-1]:
            if self.vip_queue[priority]:
                return self.vip_queue[priority].popleft()
            if self.queue[priority]:
                return self.queue[priority].popleft()
        return None

    def close(self, ticket_id: int) -> None:
        """Close a ticket."""
        if ticket_id not in self.tickets:
            raise ValueError("Ticket does not exist")
        self.tickets.pop(ticket_id)
        self.closed_tickets.add(ticket_id)

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id in self.closed_tickets:
            raise ValueError("Cannot reopen a closed ticket")
        if ticket_id not in self.tickets:
            raise ValueError("Ticket does not exist")

        customer, title, priority = self.tickets[ticket_id]
        if self.customer_vip_status[customer]:
            self.vip_queue[priority].append(ticket_id)
        else:
            self.queue[priority].append(ticket_id)
